// Draw sunflowers
const flowers = [
    {x: 100, y: 280, petals: 8, center: 30},
    {x: 200, y: 260, petals: 6, center: 25},
    {x: 300, y: 290, petals: 7, center: 32},
    {x: 150, y: 270, petals: 5, center: 28},
    {x: 250, y: 280, petals: 4, center: 24}
];

// Draw flower centers
ctx.fillStyle = '#FF69B4';
for (const flower of flowers) {
    ctx.beginPath();
    ctx.arc(flower.x, flower.y, flower.center, 0, Math.PI * 2);
    ctx.fill();
}

// Draw petals
ctx.fillStyle = '#FFD700';
for (const flower of flowers) {
    for (let i = 0; i < flower.petals; i++) {
        const angle = (i / flower.petals) * Math.PI * 2;
        const px = flower.x + Math.cos(angle) * flower.center;
        const py = flower.y + Math.sin(angle) * flower.center;
        const nextAngle = ((i + 0.5) / flower.petals) * Math.PI * 2;
        const nx = flower.x + Math.cos(nextAngle) * flower.center;
        const ny = flower.y + Math.sin(nextAngle) * flower.center;

        ctx.beginPath();
        ctx.moveTo(px, py);
        ctx.lineTo(nx, ny);
        ctx.lineTo(flower.x + Math.cos(angle) * (flower.center + 10), 
                   flower.y + Math.sin(angle) * (flower.center + 10));
        ctx.closePath();
        ctx.fill();
    }
}

