// Draw trees
function drawTree(x, y, trunkColor, foliageColor) {
    // Trunk
    ctx.fillStyle = trunkColor;
    ctx.fillRect(x - 8, y, 16, 60);

    // Foliage
    ctx.fillStyle = foliageColor;
    ctx.beginPath();
    ctx.moveTo(x - 30, y);
    ctx.lineTo(x + 30, y);
    ctx.lineTo(x + 20, y - 80);
    ctx.lineTo(x - 20, y - 80);
    ctx.closePath();
    ctx.fill();
}

