// Draw trees
function drawTree(x, y, trunkColor, leafColor) {
    // Trunk
    ctx.fillStyle = trunkColor;
    ctx.fillRect(x - 8, y, 16, 60);

    // Leaves
    ctx.fillStyle = leafColor;
    ctx.beginPath();
    ctx.moveTo(x - 30, y);
    ctx.lineTo(x + 30, y);
    ctx.lineTo(x, y - 60);
    ctx.closePath();
    ctx.fill();
}

